insert into public.shop_products(id,category_id,name,brand,description,details,images,base_price_iqd,active,source_url,source_price_note) values ('1756346673','systems','منظومة ماء C.C.K التايوانية الأصلية – 6 مراحل','C.C.K','نظام RO منزلي مزوّد بمضخة ومقياس ضغط وخزان، بتصفية متعددة المراحل.','منظومة لتنقية المياه المنزلية بتقنية التناضح العكسي، تتضمن مراحل للرواسب والكربون وغشاء RO ومرشحات نهائية. تأتي مع مضخة وملحقات للتركيب.','["https://cdn.miswag.me/images/thumbs512/a283cbd0-3a52-4f35-aaf4-b401d8ce1059.png", "https://cdn.miswag.me/images/thumbs256/a283cbd3-e766-4d0f-83e4-e336c258eb5c.png"]'::jsonb,360000,false,'https://miswag.com/products/1756346673','قائمة التاجر: 300,000 د.ع؛ صفحة المنتج: 360,000 د.ع') on conflict(id) do nothing;
insert into public.shop_products(id,category_id,name,brand,description,details,images,base_price_iqd,active,source_url,source_price_note) values ('1756120543','spares','مضخة C.C.K للأجهزة المنزلية 24 فولت','C.C.K','مضخة تعزيز ضغط الماء للأنظمة المنزلية التي تعمل بالتناضح العكسي.','مضخة Booster Pump تعمل بجهد DC 24V مخصصة لأجهزة RO المنزلية، وتُستخدم لرفع ضغط الماء قبل الممبرين. تأكد من توافقها مع جهازك قبل الطلب.','["https://cdn.miswag.me/images/thumbs512/9fc386b4-7868-4b5b-a77e-68186fee612d.jpg"]'::jsonb,40000,false,'https://miswag.com/products/1756120543','قائمة التاجر: 35,000 د.ع؛ صفحة المنتج: 40,000 د.ع') on conflict(id) do nothing;
insert into public.shop_products(id,category_id,name,brand,description,details,images,base_price_iqd,active,source_url,source_price_note) values ('1742899302','spares','خزان ماء لجهاز التحلية','عام','خزان تخزين مياه يستخدم مع بعض أجهزة التحلية المنزلية.','خزان مخصص لأنظمة تنقية المياه. السعة ومقاس الوصلات والتوافق مع الجهاز بحاجة إلى تأكيد من المجموعة قبل الشراء.','[]'::jsonb,20000,false,'https://miswag.com/products/1742899302','') on conflict(id) do nothing;
